// Process incoming webhook data from website upload
const webhookData = $node["Website Upload Webhook"].json;

console.log('=== WEBSITE UPLOAD WEBHOOK RECEIVED ===');
console.log('Webhook data:', JSON.stringify(webhookData, null, 2));

// Extract company information
const companyInfo = webhookData.companyInfo || {};
const uploadedFiles = webhookData.uploadedFiles || [];
const requestId = webhookData.requestId || `req_${Date.now()}`;

// Generate company ID
const companyId = companyInfo.company_id || `comp_${Date.now()}_${companyInfo.companyName?.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase()}`;

console.log(`Company ID: ${companyId}`);
console.log(`Company Name: ${companyInfo.companyName}`);
console.log(`Files uploaded: ${uploadedFiles.length}`);

// Validate required data
if (!companyInfo.companyName) {
  throw new Error('Company name is required');
}

// Process uploaded files
const processedFiles = uploadedFiles.map((file, index) => {
  console.log(`File ${index + 1}: ${file.name} (${file.size} bytes)`);
  return {
    id: file.id || `file_${Date.now()}_${index}`,
    name: file.name,
    size: file.size,
    type: file.type,
    content: file.content, // Base64 or file path
    uploadPath: file.uploadPath || `/uploads/${companyId}/${file.name}`
  };
});

console.log('=== PROCESSING SUMMARY ===');
console.log(`Request ID: ${requestId}`);
console.log(`Company: ${companyInfo.companyName}`);
console.log(`Files to process: ${processedFiles.length}`);
console.log('===========================');

// Return processed data for next node
return {
  json: {
    // Company information
    company_id: companyId,
    company_name: companyInfo.companyName,
    company_description: companyInfo.description || '',
    contact_email: companyInfo.contactEmail || '',
    contact_phone: companyInfo.contactPhone || '',
    website_url: companyInfo.websiteUrl || '',
    industry: companyInfo.industry || 'Technology',

    // File information
    uploaded_files: processedFiles,
    file_count: processedFiles.length,

    // Request metadata
    request_id: requestId,
    processing_started_at: new Date().toISOString(),
    source: 'website_upload'
  }
};

// Process section generation request
const webhookData = $node["Generate Section Webhook"].json;

console.log('=== SECTION GENERATION WEBHOOK RECEIVED ===');
console.log('Webhook data:', JSON.stringify(webhookData, null, 2));

// Extract request information
const companyId = webhookData.companyId || webhookData.company_id;
const sectionType = webhookData.sectionType || 'introduction';
const requestId = webhookData.requestId || `req_${Date.now()}`;

console.log(`Company ID: ${companyId}`);
console.log(`Section Type: ${sectionType}`);
console.log(`Request ID: ${requestId}`);

// Validate required data
if (!companyId) {
  throw new Error('Company ID is required');
}

// Return processed data for next node
return {
  json: {
    company_id: companyId,
    section_type: sectionType,
    request_id: requestId,
    processing_started_at: new Date().toISOString(),
    source: 'section_generation'
  }
};

// Simple function to return success response for upload
const uploadData = $json;

console.log('=== UPLOAD PROCESSING COMPLETE ===');
console.log(`Company: ${uploadData.company_name}`);
console.log(`Files processed: ${uploadData.file_count}`);

// Return success response
return {
  json: {
    success: true,
    message: 'Files uploaded and processed successfully',
    company_id: uploadData.company_id,
    company_name: uploadData.company_name,
    files_processed: uploadData.file_count,
    processing_id: uploadData.request_id,
    timestamp: new Date().toISOString()
  }
};

// Simple function to return mock section content
const sectionData = $json;

console.log('=== SECTION GENERATION COMPLETE ===');
console.log(`Company: ${sectionData.company_id}`);
console.log(`Section: ${sectionData.section_type}`);

// Generate mock section content based on section type
let sectionContent = '';
switch(sectionData.section_type) {
  case 'introduction':
    sectionContent = 'Introduction and Engagement Context: This due diligence report provides a comprehensive analysis...';
    break;
  case 'legal':
    sectionContent = 'Legal Disclaimers and Reliance Limitations: This report is prepared for informational purposes...';
    break;
  case 'methodology':
    sectionContent = 'Methodology and Source Validation: Our analysis employs industry-standard methodologies...';
    break;
  default:
    sectionContent = `${sectionData.section_type} Analysis: Detailed analysis and findings for this section...`;
}

// Return section response
return {
  json: {
    success: true,
    message: 'Section generated successfully',
    company_id: sectionData.company_id,
    section_type: sectionData.section_type,
    section_content: sectionContent,
    processing_id: sectionData.request_id,
    timestamp: new Date().toISOString()
  }
};
